#!/usr/bin/env python3
import os, base64, zlib
DATA = ""
target = os.path.join(os.path.dirname(os.path.abspath(__file__)), "wyckoff.py")
content = zlib.decompress(base64.b64decode(DATA))
with open(target, "wb") as f:
    f.write(content)
print("[OK] wyckoff.py installed ->", target)
print("[OK] Standalone -- no bitunix_scanner/ needed")
print("[OK] 1H / 15M Wyckoff spring scan")
print("")
print("Now run:  python wyckoff.py")
